def is_constrained_deadline(task_set):
    for task in task_set:
        if task.D > task.T:
            return False
    return True

def is_directly_blocked(J, t, R_k, schedule):
    if J not in top_m_effective_priorities(schedule, t):
        return False
    holder = get_holder(R_k, t)
    if holder.base_priority >= J.base_priority:
        return False
    if J.request_time[R_k] < t and not J.granted[R_k]:
        return True
    return False

def N_l(t, x, D_l, T_l):
    if t < 0:
        return 0
    return math.floor((t - x + D_l) / T_l)

def W_l(t, x, D_l, T_l):
    if t < 0:
        return 0
    n = N_l(t, x, D_l, T_l)
    remainder = t - x + D_l - T_l * n
    return x * n + min(x, remainder)

def is_reasonable_priority(task_set, m):
    low_prio_tasks = sorted(task_set, key=lambda t: t.base_prio)[- (len(task_set) - m):]
    for i in range(len(low_prio_tasks)):
        for j in range(i+1, len(low_prio_tasks)):
            if low_prio_tasks[i].base_prio < low_prio_tasks[j].base_prio and low_prio_tasks[i].D > low_prio_tasks[j].D:
                return False
    return True

def compute_I_lpi(task_i, task_set, m):
    I = 0
    for task_l in [t for t in task_set if t.base_prio > task_i.base_prio]:
        for R_x in task_l.RS:
            if |R_x| < task_i.base_prio:
                I += 2 * task_l.CT[R_x] / m
    return I

def maintain_popup_invariant(schedule, alphas):
    for t in schedule.times:
        for i in range(1, len(alphas)+1):
            assert count_popup_i(t, i) <= alphas[i-1]

def compute_RT_PIP(task_set, m):
    RT = {task.i: task.C for task in task_set}
    converged = False
    while not converged:
        converged = True
        for task_i in task_set:
            i = task_i.i
            db = compute_DB_i(task_i)
            ihp_ds = compute_I_hp_ds(task_i, RT[i])
            if i <= m:
                new_rt = task_i.C + db + ihp_ds
            else:
                ihp_os = compute_I_hp_os(task_i, RT[i])
                ihp_ns = compute_I_hp_ns(task_i, RT[i])
                ilp = compute_I_lpi(task_i, task_set, m)
                new_rt = task_i.C + db + ihp_ds + ihp_os + ihp_ns + ilp
            if abs(new_rt - RT[i]) > 1e-6:
                converged = False
            RT[i] = new_rt
    return RT
